sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float pattern;
uniform float tone;
uniform float tile;
uniform float detail;
uniform float levels;
uniform float brightness;
uniform float contrast;
layout(color) uniform half4 foreground;
layout(color) uniform half4 background;
uniform float original;
uniform float transparent;
uniform float2 offset;
uniform float chaos;
uniform float chaosAmount;
uniform float seed;
uniform float chaosSpeed;
uniform float randomPattern;
uniform float flip;
uniform float scramble;
uniform float alpha;
float hash13(float3 p) {
    p = fract(p * 0.1031);
    p += dot(p, p.zyx + 31.32);
    return fract((p.x + p.y) * p.z);
}
float glyph(float n) {
    if (n < 0.5) return 11415.0;
    if (n < 1.5) return 29330.0;
    if (n < 2.5) return 18727.0;
    if (n < 3.5) return 23213.0;
    if (n < 4.5) return 23497.0;
    if (n < 5.5) return 29671.0;
    if (n < 6.5) return 23533.0;
    if (n < 7.5) return 31183.0;
    if (n < 8.5) return 31599.0;
    return 31727.0;
}
half4 average(float2 o, float s) {
    return (image.eval(o + s * float2(0.25, 0.25)) + image.eval(o + s * float2(0.75, 0.25)) + image.eval(o + s * float2(0.25, 0.75)) + image.eval(o + s * float2(0.75, 0.75))) * 0.25;
}
float ink(float kind, float v, float2 u, float2 cell, float d) {
    float2 q = (floor(u * d) + 0.5) / d;
    if (kind < 0.5) return v > fract(0.5 + floor(u.x * d) * 0.7548776662 + floor(u.y * d) * 0.56984029) ? 1.0 : 0.0;
    if (kind < 1.5) {
        float x = floor(u.x * 5.0) - 1.0, y = floor(u.y * 7.0) - 1.0;
        if (v < 0.04 || x < 0.0 || x > 2.0 || y < 0.0 || y > 4.0) return 0.0;
        float bit = 14.0 - (y * 3.0 + x);
        return mod(floor(glyph(floor((v - 0.04) / 0.96 * 9.999)) / exp2(bit)), 2.0);
    }
    if (kind < 2.5) return abs(q.y - 0.5) * 2.0 < v ? 1.0 : 0.0;
    if (kind < 3.5) return length(q - 0.5) < 0.7072 * sqrt(v) ? 1.0 : 0.0;
    if (kind < 4.5) return abs(q.x - 0.5) * 2.0 < v ? 1.0 : 0.0;
    if (kind < 5.5) return hash13(float3(floor(u * d) + cell * 17.0, seed)) < v ? 1.0 : 0.0;
    if (kind < 6.5) return fract(length(q - 0.5) * 2.0) < v ? 1.0 : 0.0;
    if (kind < 7.5) return v;
    if (kind < 8.5) return abs(q.x - q.y) < v ? 1.0 : 0.0;
    return abs(q.x + q.y - 1.0) < v ? 1.0 : 0.0;
}
half4 main(float2 coord) {
    float s = max(tile, 1.0);
    float d = clamp(floor(detail + 0.5), 1.0, 64.0);
    float2 p = (coord - offset) / s;
    float2 cell = floor(p);
    float2 u = p - cell;
    float kind = pattern;
    float flipped = 0.0;
    float2 from = cell;
    if (chaos > 0.5) {
        float phase = chaosSpeed > 0.0 ? floor(time * chaosSpeed) : 0.0;
        float3 key = float3(cell, seed * 7.13 + phase * 3.17);
        if (hash13(key) < chaosAmount) {
            if (randomPattern > 0.5) kind = floor(hash13(key + 11.0) * 9.999);
            if (flip > 0.5) flipped = 1.0;
            if (scramble > 0.5) from = cell + floor((float2(hash13(key + 23.0), hash13(key + 37.0)) - 0.5) * 9.0);
        }
    }
    half4 c = average(from * s + offset, s);
    if (c.a <= 0.0) return mix(image.eval(coord), half4(0.0), half(clamp(alpha, 0.0, 1.0)));
    float3 rgb = float3(c.rgb) / float(c.a);
    float v = tone < 0.5 ? dot(rgb, float3(0.299, 0.587, 0.114)) : tone < 1.5 ? (rgb.r + rgb.g + rgb.b) / 3.0 : tone < 2.5 ? rgb.r : tone < 3.5 ? rgb.g : rgb.b;
    v = clamp((v - 0.5) * contrast + 0.5 + brightness, 0.0, 1.0);
    float n = max(floor(levels + 0.5), 2.0) - 1.0;
    v = floor(v * n + 0.5) / n;
    float k = ink(kind, v, u, cell, d);
    if (flipped > 0.5) k = 1.0 - k;
    half4 fg = original > 0.5 ? half4(half3(rgb), 1.0) : half4(foreground.rgb * foreground.a, foreground.a);
    half4 bg = transparent > 0.5 ? half4(0.0) : half4(background.rgb * background.a, background.a);
    half4 tiles = mix(bg, fg, half(k)) * c.a;
    return mix(image.eval(coord), tiles, half(clamp(alpha, 0.0, 1.0)));
}
